import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;

public class Main {
    static final long MOD = 1000000007L;

    static class Line {
        long a, b;
        long xStart;

        Line(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Meal {
        long a, b;

        Meal(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long n) {
        return power(n, MOD - 2);
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();
        int m = fs.nextInt();
        long k = fs.nextLong();

        long[] aSpells = new long[n];
        for (int i = 0; i < n; i++) aSpells[i] = fs.nextLong();
        long[] bSpells = new long[n];
        for (int i = 0; i < n; i++) bSpells[i] = fs.nextLong();

        long[] aMeals = new long[m];
        for (int i = 0; i < m; i++) aMeals[i] = fs.nextLong();
        long[] bMeals = new long[m];
        for (int i = 0; i < m; i++) bMeals[i] = fs.nextLong();

        // Processar refeições
        Meal[] meals = new Meal[m];
        for (int i = 0; i < m; i++) {
            meals[i] = new Meal(aMeals[i], bMeals[i]);
        }

        // Ordenar refeições: i deve vir antes de j se b_i * (a_j - 1) > b_j * (a_i - 1)
        Arrays.sort(meals, new Comparator<Meal>() {
            @Override
            public int compare(Meal m1, Meal m2) {
                long val1 = m1.b * (m2.a - 1);
                long val2 = m2.b * (m1.a - 1);
                return Long.compare(val2, val1); // Decrescente
            }
        });

        // Compor as refeições na ordem ótima: f(x) = A_meal * x + B_meal (mod MOD)
        long aMealTotal = 1;
        long bMealTotal = 0;
        for (int i = 0; i < m; i++) {
            aMealTotal = (aMealTotal * (meals[i].a % MOD)) % MOD;
            bMealTotal = ((bMealTotal * (meals[i].a % MOD)) % MOD + (meals[i].b % MOD)) % MOD;
        }

        // Processar feitiços usando Convex Hull Trick
        Line[] rawSpells = new Line[n];
        for (int i = 0; i < n; i++) {
            rawSpells[i] = new Line(aSpells[i], bSpells[i]);
        }

        // Ordenar feitiços por a crescente; para mesmo a, b decrescente
        Arrays.sort(rawSpells, new Comparator<Line>() {
            @Override
            public int compare(Line l1, Line l2) {
                if (l1.a != l2.a) return Long.compare(l1.a, l2.a);
                return Long.compare(l2.b, l1.b);
            }
        });

        // Filtrar retas com o mesmo 'a', mantendo apenas a com maior 'b'
        Line[] uniqueSpells = new Line[n];
        int uniqueCount = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || rawSpells[i].a != rawSpells[i - 1].a) {
                uniqueSpells[uniqueCount++] = rawSpells[i];
            }
        }

        // Construir a envolvente superior para x >= 0
        Line[] hull = new Line[uniqueCount];
        int top = -1;

        for (int i = 0; i < uniqueCount; i++) {
            Line curr = uniqueSpells[i];
            while (top >= 0) {
                Line prev = hull[top];
                long deltaA = curr.a - prev.a;
                long deltaB = prev.b - curr.b;
                long xCurr = (deltaB <= 0) ? 0 : (deltaB + deltaA - 1) / deltaA;

                if (xCurr <= prev.xStart) {
                    top--;
                } else {
                    break;
                }
            }

            if (top == -1) {
                curr.xStart = 0;
                hull[++top] = curr;
            } else {
                Line prev = hull[top];
                long deltaA = curr.a - prev.a;
                long deltaB = prev.b - curr.b;
                long xCurr = (deltaB <= 0) ? 0 : (deltaB + deltaA - 1) / deltaA;
                curr.xStart = xCurr;
                hull[++top] = curr;
            }
        }

        int hullSize = top + 1;

        // Responder às queries
        int q = fs.nextInt();
        while (q-- > 0) {
            long x = fs.nextLong();
            long remK = k;
            long v = x;

            if (remK > 0) {
                // Encontrar a reta inicial na envolvente para o valor v
                int low = 0, high = hullSize - 1, idx = 0;
                while (low <= high) {
                    int mid = (low + high) >>> 1;
                    if (hull[mid].xStart <= v) {
                        idx = mid;
                        low = mid + 1;
                    } else {
                        high = mid - 1;
                    }
                }

                // Se a reta atual tem a == 1
                if (hull[idx].a == 1) {
                    if (idx + 1 < hullSize) {
                        long nextX = hull[idx + 1].xStart;
                        long b = hull[idx].b;
                        if (v < nextX) {
                            long need = (nextX - v + b - 1) / b;
                            if (need <= remK) {
                                v += need * b;
                                remK -= need;
                                idx++;
                            } else {
                                v = (v + (remK % MOD) * (b % MOD)) % MOD;
                                remK = 0;
                            }
                        }
                    } else {
                        // Todas as retas têm a == 1
                        long b = hull[idx].b;
                        v = (v + (remK % MOD) * (b % MOD)) % MOD;
                        remK = 0;
                    }
                }

                // Enquanto remK > 0 e não estamos na última reta da envolvente
                while (remK > 0 && idx < hullSize - 1) {
                    while (idx + 1 < hullSize && hull[idx + 1].xStart <= v) {
                        idx++;
                    }
                    if (idx == hullSize - 1) break;

                    v = hull[idx].a * v + hull[idx].b;
                    remK--;
                }

                // Se ainda sobram passos, eles devem ser aplicados na última reta hull[hullSize - 1]
                if (remK > 0) {
                    Line last = hull[hullSize - 1];
                    long A = last.a;
                    long B = last.b;

                    if (A % MOD == 1) {
                        v = (v + (remK % MOD) * (B % MOD)) % MOD;
                    } else {
                        long Ak = power(A, remK);
                        long term1 = (Ak * (v % MOD)) % MOD;
                        long geom = (Ak - 1 + MOD) % MOD;
                        geom = (geom * modInverse((A - 1) % MOD)) % MOD;
                        long term2 = ((B % MOD) * geom) % MOD;
                        v = (term1 + term2) % MOD;
                    }
                } else {
                    v %= MOD;
                }
            } else {
                v %= MOD;
            }

            // Aplicar o combo das refeições
            long ans = ((aMealTotal * v) % MOD + bMealTotal) % MOD;
            out.println(ans);
        }

        out.flush();
    }

    // Leitor rápido de entrada para máxima performance
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }

        public long nextLong() {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            long res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }
    }
}
